index 0ce90321..bd08c165 100644
--- a/overrides/app/components/item-variant/index.test.tsx
+++ b/overrides/app/components/item-variant/index.test.tsx
@@ -30,6 +30,14 @@
  * `isDesktop` resolves to an exact, per-test value — the same pattern
  * zimmSizeSelector/index.test.tsx already establishes, rather than fighting Chakra's internal
  * breakpoint-matching media queries via a `window.matchMedia` mock.
+ *
+ * SFCC-795 (plan step 3.3) adds one more mock, `getPriceData` from `product-utils` (smallest
+ * surface, `...actual` spread keeps `getDisplayVariationValues` real for the attributes tests
+ * above, which depend on it) — see the new "promotional price (was/now)" describe block below for
+ * why: `getPriceData` requires a real product/variant shape (master/set detection, tieredPrices)
+ * this file has no reason to construct correctly, and this suite is about item-price.tsx's own
+ * forwarding/scaling contract, not about re-proving `getPriceData`'s own correctness (same
+ * reasoning this file already applies to `getDisplayVariationValues` two paragraphs up).
  */
 import React from 'react';
 import { describe, test, expect, vi, beforeEach } from 'vitest';
@@ -39,6 +47,7 @@ import { IntlProvider } from 'react-intl';
 import { MemoryRouter } from 'react-router-dom';
 import theme from 'app/theme';
 import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
+import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
 import ItemVariantProvider from '.';
 import CartItemVariantImage from './item-image';
 import CartItemVariantName from './item-name';
@@ -49,6 +58,16 @@ vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
   default: vi.fn(),
 }));

+// SFCC-795 (plan step 3.3): smallest-surface override, real `getDisplayVariationValues` kept via
+// `...actual` — see this file's own top-of-file docblock addition for why.
+vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
+  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
+  return {
+    ...actual,
+    getPriceData: vi.fn(),
+  };
+});
+
 vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
   useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
 }));
@@ -81,6 +100,7 @@ vi.mock('@chakra-ui/react', async (importOriginal) => {

 const mockUseMultiSite = vi.mocked(useMultiSite);
 const mockUseBreakpointValue = vi.mocked(useBreakpointValue);
+const mockGetPriceData = vi.mocked(getPriceData);

 // ChakraProvider with this project's own theme is required, not optional here — without it,
 // `textStyle="productNames"` resolves against Chakra's default (empty) textStyles, and
@@ -286,4 +306,70 @@ describe('item-variant', () => {
       expect(stack).toHaveStyle({ fontSize: '0.875rem', fontWeight: '500' });
     });
   });
+
+  /**
+   * SFCC-795 (plan step 3.3), pass criterion 1: "With isOnSale and a listPrice, the struck 'Was'
+   * and the 'Now' both render, and both scale with quantity." Base `display-price` (see that
+   * component's own `index.jsx`) is the mechanism: `quantity` defaults to 1 and both
+   * `currentPrice * quantity` (CurrentPrice/"Now") and `listPrice * quantity` (ListPrice/"Was",
+   * only when `listPrice` is truthy) are multiplied by whatever `quantity` this file's own
+   * `<DisplayPrice quantity={variant?.quantity} .../>` call passes through.
+   *
+   * DISCLOSED LIMITATION, verified directly against the real (unmodified, copy-first-ported)
+   * base file rather than assumed: this file's OTHER branch — `variant?.itemId` truthy, i.e. a
+   * real basket-sourced cart line item — hardcodes `listPrice: null` ("we don't want to show
+   * strikethrough price for cart since listPrice is not available via basket pricing", this
+   * file's own inline comment, byte-identical to
+   * node_modules/@salesforce/retail-react-app/app/components/item-variant/item-price.jsx, diffed
+   * directly) and passes NO `quantity` prop to `DisplayPrice` at all. So a REAL cart/basket line
+   * item cannot reach this mechanism today, regardless of Zimmermann styling — this is inherited,
+   * unmodified base SFCC behaviour (confirmed unchanged since the SFCC-270 copy-first port, plan
+   * step 2.1), not something this step's own "Changes" scope (the discountLabel prop, ProductItem
+   * only) touches or was asked to fix.
+   *
+   * This describe block therefore proves the mechanism via item-price.tsx's OTHER, non-basket
+   * branch (`variant?.itemId` falsy, `getPriceData(variant)` — the same branch this file's own
+   * docblock already documents as "for wishlist page", i.e. a real, already-existing caller shape
+   * of this exact shared component, not a fictional one) — `getPriceData` itself is mocked (see
+   * top-of-file) so this test controls `isOnSale`/`listPrice`/`currentPrice` directly rather than
+   * needing a fully realistic master/set/tieredPrices product shape.
+   *
+   * Flagged in this build's report for Marcel: pass criterion 1 is proven true of the mechanism,
+   * not proven reachable via any real Zimmermann cart line item as this file stands today.
+   */
+  describe('CartItemVariantPrice (item-price) — promotional price / was-now (SFCC-795, plan step 3.3)', () => {
+    test('isOnSale + listPrice: the struck Was and the current Now both render, and both scale with quantity', () => {
+      mockUseBreakpointValue.mockReturnValue(false);
+      mockGetPriceData.mockReturnValue({
+        currentPrice: 160,
+        listPrice: 200,
+        isOnSale: true,
+        isASet: false,
+        isMaster: false,
+        isRange: false,
+      });
+
+      const atQuantityTwo = renderWithProviders(
+        <ItemVariantProvider variant={{ id: 'variant-1', name: 'Lilac Sand Dress', quantity: 2 }}>
+          <CartItemVariantPrice currency="AUD" />
+        </ItemVariantProvider>,
+      );
+      // Now: currentPrice (160) * quantity (2).
+      expect(screen.getByText('$320.00')).toBeInTheDocument();
+      // Was: listPrice (200) * quantity (2), struck (base ListPrice renders as <Text as="s">).
+      expect(screen.getByText('$400.00')).toBeInTheDocument();
+      atQuantityTwo.unmount();
+
+      // Re-render at quantity 1 to positively prove "scale with quantity", not just correctness
+      // at one fixed value.
+      const atQuantityOne = renderWithProviders(
+        <ItemVariantProvider variant={{ id: 'variant-1', name: 'Lilac Sand Dress', quantity: 1 }}>
+          <CartItemVariantPrice currency="AUD" />
+        </ItemVariantProvider>,
+      );
+      expect(screen.getByText('$160.00')).toBeInTheDocument();
+      expect(screen.getByText('$200.00')).toBeInTheDocument();
+      atQuantityOne.unmount();
+    });
+  });
 });

