1	/*
2	 * Copyright (c) 2021, salesforce.com, inc.
3	 * All rights reserved.
4	 * SPDX-License-Identifier: BSD-3-Clause
5	 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
6	 */
7	
8	/*
9	 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-price.jsx
10	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
11	 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below and a temporary
12	 * `[overrides]` console.log marker (verified live, then removed). The
13	 * `<Stack textAlign={align} ... {...props}>`
14	 * defaults-then-spread prop order is preserved exactly, unchanged from base.
15	 *
16	 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
17	 * `display-price` and the `useCurrency`/`app/hooks` barrel are not overridden anywhere in this
18	 * repo (verified by directory listing at time of writing), so both stay on the base
19	 * `@salesforce/retail-react-app/...` path.
20	 *
21	 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec (`textStyle="price"`) via
22	 * item-variant.css.ts's `price` part. The actual price digits render via the base,
23	 * un-overridden `display-price`/`current-price` components below (out of this commit's file
24	 * scope) — confirmed by reading both that neither sets its own competing font-size, so the
25	 * textStyle cascades down via ordinary CSS inheritance rather than needing either file touched.
26	 * `PricePerItem`'s own `fontSize={{base: '12px', lg: '14px'}}` is untouched — no Figma value
27	 * was given for it at this step.
28	 */
29	import React from 'react';
30	import { FormattedMessage, FormattedNumber } from 'react-intl';
31	import {
32	  Stack,
33	  Text,
34	  useBreakpointValue,
35	  useMultiStyleConfig,
36	} from '@salesforce/retail-react-app/app/components/shared/ui';
37	import { useItemVariant } from '.';
38	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
39	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
40	// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
41	// redeclared per file.
42	import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';
43	
44	// See index.tsx's own note on why this is `any` rather than a structural type.
45	type SfccVariant = any;
46	
47	type PricePerItemProps = {
48	  currency: string;
49	  // Deviation from the base file (same labelled-comment convention as
50	  // product-view/index.tsx:659-661/1019-1022): base PropTypes declares this as optional
51	  // (`PropTypes.number`, no `.isRequired`), but both real call sites below it — the only two
52	  // in this file — only ever render <PricePerItem> from behind a `priceData?.pricePerUnit &&`
53	  // guard, so `basePrice` is never actually undefined when this renders. Typed as required to
54	  // satisfy `<FormattedNumber value={basePrice} />`'s `number | bigint` prop under strict null
55	  // checks, without inventing a fallback value the base file never had.
56	  basePrice: number;
57	};
58	
59	const PricePerItem = ({ currency, basePrice }: PricePerItemProps) => {
60	  return (
61	    <Text fontSize={{ base: '12px', lg: '14px' }}>
62	      <FormattedNumber style="currency" currency={currency} value={basePrice} />
63	      <FormattedMessage
64	        defaultMessage="ea"
65	        id="price_per_item.label.each"
66	        description="Abbreviated 'each', follows price per item, like $10/ea"
67	      />
68	    </Text>
69	  );
70	};
71	
72	type ItemPriceProps = {
73	  currency: string;
74	  align?: string;
75	  baseDirection?: string;
76	} & Record<string, any>;
77	
78	/**
79	 * In the context of a cart product item variant, this component renders the item's
80	 * pricing, taking into account applied discounts as well as base item prices.
81	 */
82	const ItemPrice = ({ currency, align = 'right', baseDirection = 'column', ...props }: ItemPriceProps) => {
83	  const variant: SfccVariant = useItemVariant();
84	  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
85	  const { price, priceAfterItemDiscount } = variant;
86	  const isASet = variant?.type?.set;
87	  const isMaster = variant?.type?.master;
88	  let priceData;
89	  // When variant has basket pricing, we should prioritize these prices for displaying
90	  // since they may have take promotion/discount into account
91	  // NOTE: try NOT to re-calculate these values since basket-level discount is complicated
92	  if (variant?.itemId) {
93	    priceData = {
94	      currentPrice: priceAfterItemDiscount,
95	      // we don't want to show strikethrough price for cart since listPrice is not available via basket pricing
96	      listPrice: null,
97	      pricePerUnit: variant?.pricePerUnit,
